import React from "react";
import {
  FaCode,
  FaAward,
  FaBriefcase,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      {/* BACKGROUND */}
      <div className="glow"></div>
      <div className="grid"></div>

      {/* HEADER */}
      <div className="header">
        <h1>Engineering Stack</h1>
        <p>Skills, certifications, and experience shaping my development journey</p>
      </div>

      {/* MAIN LAYOUT */}
      <div className="layout">

        {/* LEFT SIDE - SKILLS + CERTIFICATIONS */}
        <div className="left">

          <div className="card">
            <h2><FaCode /> Technical Skills</h2>
            <div className="tags">
              <span>Java</span>
              <span>React.js</span>
              <span>Spring Boot</span>
              <span>MySQL</span>
              <span>HTML</span>
              <span>CSS</span>
              <span>JavaScript</span>
            </div>
          </div>

          <div className="card">
            <h2><FaAward /> Certifications</h2>
            <div className="list">
              <p>Java – NPTEL</p>
              <p>Data Science for Engineers – NPTEL</p>
              <p>SQL – HackerRank</p>
              <p>Python – SoloLearn</p>
            </div>
          </div>

        </div>

        {/* RIGHT SIDE - TIMELINE */}
        <div className="right">

          <h2 className="title">Internship Experience</h2>

          <div className="timeline">

            <div className="item">
              <div className="dot"></div>
              <div>
                <h3>Full Stack Java Intern</h3>
                <p>
                  Worked on Student Portal Management System using Spring Boot.
                  Developed REST APIs, backend logic, and database integration.
                </p>
              </div>
            </div>

            <div className="item">
              <div className="dot"></div>
              <div>
                <h3>Data Analytics Intern</h3>
                <p>
                  Worked with Power BI to build interactive dashboards, clean datasets,
                  and convert raw data into meaningful business insights.
                </p>
              </div>
            </div>

          </div>
        </div>

      </div>

      {/* SOFT SKILLS BOTTOM */}
      <div className="soft">

        <h2>Soft Skills</h2>

        <div className="chips">
          <span><FaUsers /> Teamwork</span>
          <span><FaComments /> Communication</span>
          <span><FaLightbulb /> Problem Solving</span>
          <span><FaCogs /> Adaptability</span>
          <span><FaBrain /> Creativity</span>
          <span><FaUsersCog /> Leadership</span>
          <span><FaClock /> Time Management</span>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .skills-page{
          min-height:100vh;
          padding:40px 10%;
          font-family:"Poppins",sans-serif;
          background: radial-gradient(circle at top,#0b1220,#050816);
          color:white;
          position:relative;
          overflow:hidden;
        }

        /* BACKGROUND */
        .glow{
          position:absolute;
          width:500px;
          height:500px;
          background:radial-gradient(circle,#38BDF8,transparent 70%);
          top:-200px;
          right:-150px;
          filter:blur(60px);
          opacity:0.25;
        }

        .grid{
          position:absolute;
          inset:0;
          background-image:
            linear-gradient(rgba(56,189,248,0.05) 1px, transparent 1px),
            linear-gradient(90deg, rgba(56,189,248,0.05) 1px, transparent 1px);
          background-size:50px 50px;
          opacity:0.3;
        }

        /* HEADER */
        .header{
          text-align:center;
          margin-bottom:40px;
        }

        .header h1{
          font-size:42px;
          color:#38BDF8;
        }

        .header p{
          color:#94a3b8;
          margin-top:8px;
        }

        /* LAYOUT */
        .layout{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:40px;
        }

        /* LEFT */
        .left{
          display:flex;
          flex-direction:column;
          gap:20px;
        }

        .card{
          background:rgba(255,255,255,0.04);
          border:1px solid rgba(56,189,248,0.2);
          padding:20px;
          border-radius:16px;
          backdrop-filter:blur(10px);
          transition:0.3s;
        }

        .card:hover{
          transform:translateY(-6px);
          border-color:#38BDF8;
          box-shadow:0 0 25px rgba(56,189,248,0.2);
        }

        .card h2{
          color:#38BDF8;
          margin-bottom:12px;
          display:flex;
          gap:8px;
          align-items:center;
        }

        .tags{
          display:flex;
          flex-wrap:wrap;
          gap:10px;
        }

        .tags span{
          padding:6px 12px;
          border-radius:20px;
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          font-size:13px;
          color:#cbd5e1;
        }

        .list p{
          color:#cbd5e1;
          margin:6px 0;
        }

        /* RIGHT TIMELINE */
        .right{
          padding-left:20px;
        }

        .title{
          color:#38BDF8;
          margin-bottom:20px;
        }

        .timeline{
          position:relative;
        }

        .timeline::before{
          content:"";
          position:absolute;
          left:7px;
          top:0;
          bottom:0;
          width:2px;
          background:#38BDF8;
          opacity:0.4;
        }

        .item{
          display:flex;
          gap:15px;
          margin-bottom:25px;
        }

        .dot{
          width:12px;
          height:12px;
          border-radius:50%;
          background:#38BDF8;
          box-shadow:0 0 10px #38BDF8;
          margin-top:6px;
        }

        .item h3{
          color:#38BDF8;
          margin-bottom:5px;
        }

        .item p{
          color:#cbd5e1;
          line-height:1.5;
        }

        /* SOFT SKILLS */
        .soft{
          margin-top:50px;
          text-align:center;
        }

        .soft h2{
          color:#38BDF8;
          margin-bottom:20px;
        }

        .chips{
          display:flex;
          flex-wrap:wrap;
          justify-content:center;
          gap:12px;
        }

        .chips span{
          padding:8px 14px;
          border-radius:20px;
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          display:flex;
          gap:6px;
          align-items:center;
          color:#cbd5e1;
        }

        /* RESPONSIVE */
        @media(max-width:900px){
          .layout{
            grid-template-columns:1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Skills;
